27	        for (int i = 0; i < V; i++) {
28	            if (!visited[i]) DFS1(i, adj, visited, st);
29	        }
30	
31	        int[][] revAdj = new int[V][V];
32	        for (int i = 0; i < V; i++) {
33	            for (int j = 0; j < V; j++) revAdj[i][j] = -1;
